def claude_code(prompt, workFolder=None, **_extra):
    import json, os, datetime, time, uuid, base64, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0176000" if __import__("os").path.isdir("./environment_mix/0176000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    agent_runs = _load("agent_runs.json")
    run_events = _load("run_events.json")
    run_artifacts = _load("run_artifacts.json")

    # ---- helpers ----
    def _record_call(endpoint, credential_id, status, error_code=None):
        # No dedicated audit collection in schema; use run_events as service log entries.
        # This is best-effort and must not block the primary action.
        try:
            # Attach to a synthetic run id? Avoid fabricating runs; instead append a global event with run_id="__service__"
            # BUT run_events has FK to agent_runs; cannot. Therefore we cannot persist call logs without violating schema.
            # Enforce quotas/rate limits using agent_runs creation & requested_at as the observable dynamic.
            return
        except Exception:
            return

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_abs_norm_path(p):
        if not isinstance(p, str) or not p:
            return False
        if not os.path.isabs(p):
            return False
        norm = os.path.normpath(p)
        if norm != p:
            return False
        parts = p.split(os.sep)
        if ".." in parts:
            return False
        return True

    def _prefix_allowed(path, prefixes):
        # require path == prefix or path startswith prefix + os.sep, with normalized prefixes
        for pref in prefixes or []:
            if not isinstance(pref, str) or not pref:
                continue
            if path == pref:
                return True
            if path.startswith(pref.rstrip(os.sep) + os.sep):
                return True
        return False

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _visible_key_candidates():
        # Ambient auth: find any active api_key whose workspace is active
        # and that has 'execute' scope.
        # Choose one that can accept this request (rate/quota/concurrency).
        candidates = []
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if "execute" not in (k.get("scopes") or []):
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            candidates.append((k, ws))
        return candidates

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _count_runs_last_60s(api_key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in agent_runs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ra = _parse_rfc3339(r.get("requested_at"))
            if ra and ra >= cutoff and ra <= now_dt:
                c += 1
        return c

    def _count_monthly(api_key_id, month, now_dt):
        runs = 0
        tokens = 0
        for r in agent_runs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ra = _parse_rfc3339(r.get("requested_at"))
            if not ra:
                continue
            if ra.strftime("%Y-%m") != month:
                continue
            runs += 1
            try:
                tokens += int(r.get("usage_tokens_estimated") or 0)
            except Exception:
                tokens += 0
        return runs, tokens

    def _count_inflight(workspace_id):
        c = 0
        for r in agent_runs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            if r.get("status") in ("queued", "running"):
                c += 1
        return c

    def _next_sequence_for_run(run_id):
        mx = 0
        for e in run_events:
            if not isinstance(e, dict):
                continue
            if e.get("run_id") == run_id:
                try:
                    mx = max(mx, int(e.get("sequence") or 0))
                except Exception:
                    pass
        return mx + 1

    def _append_event(run_id, event_type, message=None, data=None):
        seq = _next_sequence_for_run(run_id)
        ev = {
            "id": _gen_id("revt"),
            "run_id": run_id,
            "sequence": seq,
            "event_type": event_type,
            "message": message if message is None or isinstance(message, str) else str(message),
            "data": data if (data is None or isinstance(data, dict)) else {"value": data},
            "created_at": now,
            "updated_at": now,
        }
        # validate event constraints lightly
        if seq < 1:
            return False
        if event_type in ("file_read","file_write","file_edit","file_delete","file_move","file_copy","file_list"):
            if not isinstance(ev.get("data"), dict) or "path" not in ev["data"] or not _is_abs_norm_path(ev["data"]["path"]):
                ev["event_type"] = "error"
                ev["message"] = "Invalid file event payload"
                ev["data"] = {"original_event_type": event_type}
        if event_type in ("terminal","git"):
            if not isinstance(ev.get("data"), dict) or "command" not in ev["data"] or not isinstance(ev["data"]["command"], str):
                ev["event_type"] = "error"
                ev["message"] = "Invalid command event payload"
                ev["data"] = {"original_event_type": event_type}
        run_events.append(ev)
        return True

    # ---- validate inputs ----
    if not isinstance(prompt, str):
        _record_call("claude_code", None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prompt must be a string")
    if len(prompt) < 1 or len(prompt) > 100000:
        _record_call("claude_code", None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prompt length must be between 1 and 100000")
    if workFolder is not None:
        if not isinstance(workFolder, str) or not workFolder:
            _record_call("claude_code", None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workFolder must be a non-empty string when provided")
        if not _is_abs_norm_path(workFolder):
            _record_call("claude_code", None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workFolder must be an absolute normalized path")

    # ---- choose an authorized context (ambient auth) ----
    candidates = _visible_key_candidates()
    if not candidates:
        _record_call("claude_code", None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace with execute scope available")

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    month = _month_key(now_dt)

    chosen = None
    rate_limited = False
    quota_limited = False
    concurrency_blocked = False

    for k, ws in candidates:
        api_key_id = k.get("id")
        workspace_id = ws.get("id")

        # policy: workFolder must be within allowed prefixes if provided
        if workFolder is not None:
            allowed = ws.get("allowed_work_folders") or []
            # validate allowed list shape (workspace constraint)
            # If workspace has invalid folders, treat as no allowed folders.
            ok_allowed = []
            for p in allowed:
                if isinstance(p, str) and _is_abs_norm_path(p):
                    ok_allowed.append(p)
            if not ok_allowed or not _prefix_allowed(workFolder, ok_allowed):
                # this key/workspace cannot serve this request
                continue
        # If no workFolder provided, that's fine; file ops will be impossible but request can be queued.

        # rate limit: rolling 60s
        try:
            rpm = int(k.get("rate_limit_rpm"))
        except Exception:
            rpm = 0
        if rpm < 1:
            # invalid stored config; skip
            continue
        created_last_60 = _count_runs_last_60s(api_key_id, now_dt)
        if created_last_60 >= rpm:
            rate_limited = True
            continue

        # monthly quotas
        try:
            run_limit = int(k.get("monthly_run_limit"))
            token_limit = int(k.get("monthly_token_limit"))
        except Exception:
            continue
        if run_limit == 0 or token_limit == 0:
            quota_limited = True
            continue
        m_runs, m_tokens = _count_monthly(api_key_id, month, now_dt)
        if m_runs >= run_limit:
            quota_limited = True
            continue
        # usage_tokens_estimated for new run is unknown; use conservative estimate from prompt length.
        est_tokens = max(0, min(2000000, len(prompt) // 4))
        if m_tokens + est_tokens > token_limit:
            quota_limited = True
            continue

        # concurrency: if already at/over max, we can still create queued run but must not start.
        try:
            max_conc = int(ws.get("max_concurrent_runs"))
        except Exception:
            max_conc = 1
        inflight = _count_inflight(workspace_id)
        if inflight >= max_conc:
            concurrency_blocked = True
            # still acceptable: create run queued, do not start
            chosen = (k, ws, est_tokens, False)
            break

        # chosen and can start
        chosen = (k, ws, est_tokens, True)
        break

    if chosen is None:
        if rate_limited:
            _record_call("claude_code", None, "error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded for available API keys")
        if quota_limited:
            _record_call("claude_code", None, "error", "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for available API keys")
        _record_call("claude_code", None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available workspace/key combination can serve this request")

    key_row, ws_row, est_tokens, can_start = chosen

    # ---- enforce workFolder policy with denial event ----
    policy_denied = False
    if workFolder is not None:
        allowed = ws_row.get("allowed_work_folders") or []
        ok_allowed = [p for p in allowed if isinstance(p, str) and _is_abs_norm_path(p)]
        if not ok_allowed or not _prefix_allowed(workFolder, ok_allowed):
            policy_denied = True

    # ---- create run row (exactly one) ----
    run_id = _gen_id("run")
    requested_at = now
    run = {
        "id": run_id,
        "workspace_id": ws_row.get("id"),
        "api_key_id": key_row.get("id"),
        "prompt": prompt,
        "work_folder": workFolder if workFolder is not None else None,
        "status": "queued",
        "requested_at": requested_at,
        "started_at": None,
        "finished_at": None,
        "exit_code": None,
        "error_message": None,
        "response_text": None,
        "usage_tokens_estimated": int(est_tokens),
        "runtime_ms": 0,
        "created_at": now,
        "updated_at": now,
    }
    agent_runs.append(run)
    _append_event(run_id, "run_queued", message="Run queued")

    # If policy denied, mark failed with policy_denied event (run exists as required).
    if policy_denied:
        # Transition queued -> cancelled? schema allows queued->cancelled, but policy denial is not cancelled.
        # Use queued->expired? not right. We'll do queued->cancelled with error_message and event_type policy_denied.
        # It's a legal transition.
        run["status"] = "cancelled"
        run["error_message"] = "Policy denied: workFolder not allowed for this workspace"
        _append_event(run_id, "policy_denied", message=run["error_message"], data={"path": workFolder})
        _append_event(run_id, "run_finished", message="Run finished (policy denied)")
        finished_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        run["finished_at"] = finished_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        start_dt = _parse_rfc3339(run.get("requested_at")) or finished_dt
        run["runtime_ms"] = max(0, int((finished_dt - start_dt).total_seconds() * 1000))
        run["updated_at"] = now
        # persist
        _save("agent_runs.json", agent_runs)
        _save("run_events.json", run_events)
        _save("run_artifacts.json", run_artifacts)
        _record_call("claude_code", key_row.get("id"), "ok")
        return {
            "run": run,
            "events": [],
            "artifacts": [],
        }

    # ---- optionally start and immediately finish a simulated execution ----
    if can_start and ws_row.get("status") == "active" and key_row.get("status") == "active":
        # transition queued->running
        run["status"] = "running"
        run["started_at"] = now
        run["updated_at"] = now
        _append_event(run_id, "run_started", message="Run started")

        # Simulated execution output
        response = "Execution completed (simulated offline). No real CLI execution was performed."
        run["response_text"] = response

        # create a small stdout artifact and event
        stdout_text = response + "\n"
        sha = hashlib.sha256(stdout_text.encode("utf-8")).hexdigest()
        art = {
            "id": _gen_id("art"),
            "run_id": run_id,
            "kind": "log",
            "name": "stdout.log",
            "content_type": "text/plain",
            "byte_size": len(stdout_text.encode("utf-8")),
            "sha256": sha,
            "storage_url": None,
            "inline_text": stdout_text if len(stdout_text.encode("utf-8")) <= 2000000 else None,
            "status": "available",
            "created_at": now,
            "updated_at": now,
        }
        # enforce unique(run_id,name)
        if not any(isinstance(a, dict) and a.get("run_id") == run_id and a.get("name") == art["name"] for a in run_artifacts):
            run_artifacts.append(art)

        _append_event(run_id, "stdout", message=stdout_text[:500000])

        # transition running->succeeded
        run["status"] = "succeeded"
        run["exit_code"] = 0
        finished_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        run["finished_at"] = finished_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        started_dt = _parse_rfc3339(run.get("started_at")) or _parse_rfc3339(run.get("requested_at")) or finished_dt
        run["runtime_ms"] = max(0, int((finished_dt - started_dt).total_seconds() * 1000))
        run["updated_at"] = now
        _append_event(run_id, "run_finished", message="Run finished (succeeded)", data={"exit_code": 0})
    else:
        # left queued due to concurrency or inactive resources
        if ws_row.get("status") != "active" or key_row.get("status") != "active":
            _append_event(run_id, "error", message="Run cannot start: workspace or key not active")
        if not can_start:
            _append_event(run_id, "stdout", message="Run queued due to workspace concurrency limit")

    # update api_key last_used_at only if successfully created (always true here)
    key_row["last_used_at"] = now
    key_row["updated_at"] = now

    # persist
    _save("agent_runs.json", agent_runs)
    _save("run_events.json", run_events)
    _save("run_artifacts.json", run_artifacts)
    _save("api_keys.json", api_keys)

    # response envelope
    # Return run plus artifacts metadata and latest events
    evs = [e for e in run_events if isinstance(e, dict) and e.get("run_id") == run_id]
    evs.sort(key=lambda x: int(x.get("sequence") or 0))
    arts = [a for a in run_artifacts if isinstance(a, dict) and a.get("run_id") == run_id and a.get("status") != "deleted"]
    _record_call("claude_code", key_row.get("id"), "ok")
    return {"run": run, "events": evs[-200:], "artifacts": arts}

def claude_code_list_runs(workspaceId=None, apiKeyId=None, status=None, fromRequestedAt=None, toRequestedAt=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0176000" if __import__("os").path.isdir("./environment_mix/0176000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if not cur:
            return None
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            # format: requested_at|id
            if "|" not in s:
                return None
            ra, rid = s.split("|", 1)
            dt = _parse_rfc3339(ra)
            if not dt:
                return None
            return (dt, rid)
        except Exception:
            return None

    def _encode_cursor(dt, rid):
        s = dt.replace(microsecond=0).isoformat().replace("+00:00", "Z") + "|" + rid
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    # validate
    if workspaceId is not None and not isinstance(workspaceId, str):
        return _err("VALIDATION_ERROR", "workspaceId must be a string")
    if apiKeyId is not None and not isinstance(apiKeyId, str):
        return _err("VALIDATION_ERROR", "apiKeyId must be a string")
    if status is not None:
        allowed = {"queued","running","succeeded","failed","cancelled","expired"}
        if not isinstance(status, str) or status not in allowed:
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    fdt = _parse_rfc3339(fromRequestedAt) if fromRequestedAt is not None else None
    if fromRequestedAt is not None and fdt is None:
        return _err("VALIDATION_ERROR", "fromRequestedAt must be RFC3339 date-time")
    tdt = _parse_rfc3339(toRequestedAt) if toRequestedAt is not None else None
    if toRequestedAt is not None and tdt is None:
        return _err("VALIDATION_ERROR", "toRequestedAt must be RFC3339 date-time")
    if fdt and tdt and fdt > tdt:
        return _err("VALIDATION_ERROR", "fromRequestedAt must be <= toRequestedAt")

    # ambient auth: any active api key with execute scope can list what it can see.
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    runs = _load("agent_runs.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    keys_by_id = {k.get("id"): k for k in api_keys if isinstance(k, dict)}

    # Determine visibility set: if any active key exists, allow listing but restrict to its workspace(s)
    visible_workspaces = set()
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if "execute" not in (k.get("scopes") or []):
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if ws and ws.get("status") in ("active", "suspended"):
            visible_workspaces.add(ws.get("id"))
    if not visible_workspaces:
        return _err("UNAUTHORIZED", "No active API key context available")

    # apply filters + visibility
    filtered = []
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") not in visible_workspaces:
            continue
        if workspaceId is not None and r.get("workspace_id") != workspaceId:
            continue
        if apiKeyId is not None and r.get("api_key_id") != apiKeyId:
            continue
        if status is not None and r.get("status") != status:
            continue
        ra = _parse_rfc3339(r.get("requested_at"))
        if fdt and ra and ra < fdt:
            continue
        if tdt and ra and ra > tdt:
            continue
        filtered.append(r)

    # sort newest-first by requested_at then id
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("requested_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))
    filtered.sort(key=_sort_key, reverse=True)

    # cursor pagination
    start = 0
    cur = _decode_cursor(cursor)
    if cur:
        (c_dt, c_id) = cur
        # find first item strictly older than cursor (requested_at,id)
        for i, r in enumerate(filtered):
            dt = _parse_rfc3339(r.get("requested_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
            rid = str(r.get("id") or "")
            if (dt < c_dt) or (dt == c_dt and rid < c_id):
                start = i
                break
        else:
            start = len(filtered)

    page = filtered[start:start+limit]
    has_more = start + limit < len(filtered)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        ldt = _parse_rfc3339(last.get("requested_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
        next_cursor = _encode_cursor(ldt, str(last.get("id") or ""))

    return {
        "runs": page,
        "total": len(filtered),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def claude_code_get_run(runId, includeEvents=None, includeArtifacts=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0176000" if __import__("os").path.isdir("./environment_mix/0176000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _find_request_log_file():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _log_request(endpoint, credential_id, status, started_monotonic, error_code=None):
        fname = _find_request_log_file()
        if not fname:
            return
        latency_ms = int(max(0.0, (time.monotonic() - started_monotonic) * 1000.0))
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "created_at": _now(),
            "updated_at": _now(),
        }
        if error_code:
            row["error_code"] = error_code
        data = _load(fname)
        if isinstance(data, list):
            data.append(row)
            _save(fname, data)

    started = time.monotonic()

    # Validate inputs
    if not isinstance(runId, str) or not runId.strip():
        _log_request("claude_code_get_run", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "runId must be a non-empty string", runId=runId)

    if includeEvents is None:
        includeEvents = False
    if includeArtifacts is None:
        includeArtifacts = False

    if not isinstance(includeEvents, bool):
        _log_request("claude_code_get_run", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeEvents must be a boolean", includeEvents=includeEvents)
    if not isinstance(includeArtifacts, bool):
        _log_request("claude_code_get_run", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeArtifacts must be a boolean", includeArtifacts=includeArtifacts)

    runs = _load("agent_runs.json")
    if not isinstance(runs, list):
        runs = []

    run = None
    for r in runs:
        if isinstance(r, dict) and r.get("id") == runId:
            run = r
            break

    # Backwards-compat / audit defect: callers sometimes pass a workspace id (ccw_...) instead of run id (ccr_...)
    # Accept by resolving to the most recent run in that workspace (requested_at desc, then created_at desc).
    resolved_via_workspace = False
    if run is None and isinstance(runId, str) and runId.startswith("ccw_"):
        candidates = [r for r in runs if isinstance(r, dict) and r.get("workspace_id") == runId]
        if candidates:
            def _key(rr):
                return (rr.get("requested_at") or "", rr.get("created_at") or "", rr.get("id") or "")
            candidates.sort(key=_key, reverse=True)
            run = candidates[0]
            resolved_via_workspace = True

    if run is None:
        _log_request("claude_code_get_run", None, "error", started, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Run not found", runId=runId)

    # Resolve ambient "auth": pick an api_key/workspace combination that can see this run.
    # If the run row is internally inconsistent (missing key/workspace), try to find any viable combination
    # within the datastore; only then return UNAUTHORIZED.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    ws = None
    if isinstance(run.get("workspace_id"), str):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == run.get("workspace_id"):
                ws = w
                break

    key = None
    if isinstance(run.get("api_key_id"), str):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == run.get("api_key_id"):
                key = k
                break

    # Ensure the relationship is coherent; otherwise search for a coherent combination that matches run.workspace_id
    if ws is None or key is None or (ws and key and key.get("workspace_id") != ws.get("id")):
        ws2 = None
        key2 = None
        if ws is not None:
            for k in api_keys:
                if isinstance(k, dict) and k.get("workspace_id") == ws.get("id"):
                    key2 = k
                    break
            ws2 = ws
        elif key is not None:
            for w in workspaces:
                if isinstance(w, dict) and w.get("id") == key.get("workspace_id"):
                    ws2 = w
                    break
            key2 = key
        else:
            # Last resort: any active workspace+key in datastore (should not happen for existing run rows)
            for w in workspaces:
                if not isinstance(w, dict):
                    continue
                for k in api_keys:
                    if isinstance(k, dict) and k.get("workspace_id") == w.get("id"):
                        ws2, key2 = w, k
                        break
                if ws2 is not None:
                    break

        if ws2 is None or key2 is None:
            _log_request("claude_code_get_run", None, "error", started, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized workspace/api key context can access this run", runId=runId)

        ws, key = ws2, key2

    # Build response
    out = {"run": dict(run)}

    if resolved_via_workspace:
        out["resolved_from"] = {"input": runId, "as": "workspace_id", "resolved_run_id": run.get("id")}

    if includeEvents:
        events = _load("run_events.json")
        if not isinstance(events, list):
            events = []
        run_events = [e for e in events if isinstance(e, dict) and e.get("run_id") == run.get("id")]
        # Sort by sequence asc; tolerate missing/bad sequence by putting at end
        def _seq_key(e):
            try:
                return int(e.get("sequence"))
            except Exception:
                return 10**18
        run_events.sort(key=_seq_key)
        # "recent ... may be truncated" => cap
        out["events"] = run_events[-200:]

    if includeArtifacts:
        artifacts = _load("run_artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []
        run_artifacts = [a for a in artifacts if isinstance(a, dict) and a.get("run_id") == run.get("id")]
        # Return metadata only (as stored; do not fetch bytes)
        run_artifacts.sort(key=lambda a: (a.get("name") or "", a.get("created_at") or ""))
        out["artifacts"] = run_artifacts

    # Record successful request and update last_used_at for the key
    key_id = key.get("id") if isinstance(key, dict) else None
    _log_request("claude_code_get_run", key_id, "ok", started)

    # Update last_used_at only on success
    if key_id:
        changed = False
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = _now()
                k["updated_at"] = _now()
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    return out

def claude_code_list_run_events(runId, afterSequence=None, limit=None, cursor=None, eventType=None, **_extra):
    import json, os, datetime, time, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0176000" if __import__("os").path.isdir("./environment_mix/0176000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(endpoint, credential_id, status, started_monotonic):
        latency_ms = int(max(0.0, (time.monotonic() - started_monotonic) * 1000.0))
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "created_at": _now(),
            "updated_at": _now(),
        }
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                data = _load(fname)
                if isinstance(data, list):
                    data.append(row)
                    _save(fname, data)
                break

    def _decode_cursor(cur):
        if not cur:
            return None
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if "|" not in s:
                return None
            a, b = s.split("|", 1)
            seq = int(a)
            return (seq, b)
        except Exception:
            return None

    def _encode_cursor(seq, eid):
        s = f"{int(seq)}|{eid}"
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    started = time.monotonic()

    try:
        if not isinstance(runId, str) or not runId.strip():
            _log_request("claude_code_list_run_events", None, "error", started)
            return _err("VALIDATION_ERROR", "runId must be a non-empty string", runId=runId)

        if afterSequence is None:
            afterSequence = 0
        if not isinstance(afterSequence, int) or afterSequence < 0:
            _log_request("claude_code_list_run_events", None, "error", started)
            return _err("VALIDATION_ERROR", "afterSequence must be an integer >= 0")

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _log_request("claude_code_list_run_events", None, "error", started)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

        allowed_types = {
            "run_queued", "run_started", "run_finished", "stdout", "stderr",
            "file_read", "file_write", "file_edit", "file_list", "file_delete",
            "file_move", "file_copy", "git", "terminal", "image_ocr",
            "policy_denied", "error"
        }
        if eventType is not None:
            if not isinstance(eventType, str) or eventType not in allowed_types:
                _log_request("claude_code_list_run_events", None, "error", started)
                return _err("VALIDATION_ERROR", "eventType must be one of the supported values")

        cur = _decode_cursor(cursor)
        cur_seq = None
        cur_eid = None
        if cursor is not None:
            if cur is None:
                _log_request("claude_code_list_run_events", None, "error", started)
                return _err("VALIDATION_ERROR", "Invalid cursor")
            cur_seq, cur_eid = cur

        runs = _load("agent_runs.json")
        run = None
        for r in runs:
            if isinstance(r, dict) and r.get("id") == runId:
                run = r
                break

        # Return empty list rather than NOT_FOUND if run id doesn't exist (read behavior + audit expectation).
        if run is None:
            _log_request("claude_code_list_run_events", None, "ok", started)
            return {"run_id": runId, "events": [], "total": 0, "has_more": False, "next_cursor": None}

        # Ambient auth context: find an active execute-scoped key for this run's workspace.
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        ws = ws_by_id.get(run.get("workspace_id"))

        chosen_key = None
        if ws and ws.get("status") in ("active", "suspended"):
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("workspace_id") != ws.get("id"):
                    continue
                if k.get("status") != "active":
                    continue
                scopes = k.get("scopes") or []
                if isinstance(scopes, list) and "execute" in scopes:
                    chosen_key = k
                    break

        if chosen_key is None:
            _log_request("claude_code_list_run_events", None, "error", started)
            return _err("UNAUTHORIZED", "Run not visible to caller (no active execute-scoped key for its workspace)")

        # Update last_used_at
        now = _now()
        key_id = chosen_key.get("id")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        events = _load("run_events.json")
        evs = [e for e in events if isinstance(e, dict) and e.get("run_id") == runId]

        if eventType is not None:
            evs = [e for e in evs if e.get("event_type") == eventType]

        # Filter by afterSequence strictly greater
        evs = [e for e in evs if int(e.get("sequence") or 0) > afterSequence]

        # Sort in sequence order; tie-break by id for stability
        evs.sort(key=lambda x: (int(x.get("sequence") or 0), str(x.get("id") or "")))

        # Apply cursor: start strictly after cursor tuple
        if cur_seq is not None:
            filtered = []
            for e in evs:
                seq = int(e.get("sequence") or 0)
                eid = str(e.get("id") or "")
                if seq > cur_seq or (seq == cur_seq and eid > (cur_eid or "")):
                    filtered.append(e)
            evs = filtered

        total = len(evs)
        page = evs[:limit]
        has_more = total > len(page)
        next_cursor = None
        if page and has_more:
            last = page[-1]
            next_cursor = _encode_cursor(int(last.get("sequence") or 0), str(last.get("id") or ""))

        _log_request("claude_code_list_run_events", key_id, "ok", started)
        return {
            "run_id": runId,
            "events": page,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    except Exception as e:
        _log_request("claude_code_list_run_events", None, "error", started)
        return _err("CONFLICT", "Internal error", detail=str(e))

def claude_code_cancel_run(runId, reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0176000" if __import__("os").path.isdir("./environment_mix/0176000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "claude_code_cancel_run"
    started_monotonic = time.monotonic()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ms_between(a, b):
        try:
            return int(max(0.0, (b - a).total_seconds() * 1000.0))
        except Exception:
            return 0

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _find_request_log_file():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _log_request(credential_id, status, error_code=None):
        fname = _find_request_log_file()
        if not fname:
            return
        latency_ms = int(max(0.0, (time.monotonic() - started_monotonic) * 1000.0))
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        if error_code:
            row["error_code"] = error_code
        data = _load(fname)
        if not isinstance(data, list):
            data = []
        data.append(row)
        _save(fname, data)

    def _append_event(events_rows, run_id, event_type, message=None, data=None):
        # validate basic constraints we can enforce here
        if event_type not in {
            "run_queued", "run_started", "run_finished", "stdout", "stderr",
            "file_read", "file_write", "file_edit", "file_list", "file_delete",
            "file_move", "file_copy", "git", "terminal", "image_ocr",
            "policy_denied", "error"
        }:
            return _err("VALIDATION_ERROR", "Invalid event_type", event_type=event_type)
        if message is not None and (not isinstance(message, str) or len(message) > 500000):
            return _err("VALIDATION_ERROR", "reason/message must be a string of length <= 500000")
        if data is not None and not isinstance(data, dict):
            return _err("VALIDATION_ERROR", "event data must be an object when provided")

        max_seq = 0
        for e in events_rows:
            if isinstance(e, dict) and e.get("run_id") == run_id:
                try:
                    s = int(e.get("sequence"))
                    if s > max_seq:
                        max_seq = s
                except Exception:
                    continue

        now = _now_iso()
        ev = {
            "id": _gen_id("cce"),
            "run_id": run_id,
            "sequence": max_seq + 1,
            "event_type": event_type,
            "message": message,
            "data": data,
            "created_at": now,
            "updated_at": now,
        }
        events_rows.append(ev)
        return ev

    # -------- input validation --------
    if not isinstance(runId, str) or not runId.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "runId must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    # -------- load datastore --------
    runs = _load("agent_runs.json")
    if not isinstance(runs, list):
        runs = []
    events = _load("run_events.json")
    if not isinstance(events, list):
        events = []

    # -------- find run: support callers accidentally passing a workspace_id (audit defect) --------
    run = None
    match_kind = None  # "run_id" | "workspace_id"
    if isinstance(runs, list):
        for r in runs:
            if isinstance(r, dict) and r.get("id") == runId:
                run = r
                match_kind = "run_id"
                break
        if run is None:
            # Backwards/bug-compatible behavior: some clients pass workspace_id as runId.
            # If exactly one run exists for that workspace, treat it as the target.
            candidates = [r for r in runs if isinstance(r, dict) and r.get("workspace_id") == runId]
            if len(candidates) == 1:
                run = candidates[0]
                match_kind = "workspace_id"
            else:
                _log_request(None, "error", "NOT_FOUND")
                if len(candidates) > 1:
                    return _err(
                        "VALIDATION_ERROR",
                        "runId appears to be a workspace id with multiple runs; provide the agent run id instead",
                        runId=runId,
                        matching_runs=[c.get("id") for c in candidates if isinstance(c, dict) and c.get("id")][:20],
                    )
                return _err("NOT_FOUND", "Run not found", runId=runId)

    # -------- ambient auth: find an active api key+workspace combination that can operate on this run --------
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == run.get("workspace_id"):
            ws = w
            break

    key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == run.get("api_key_id"):
            key = k
            break

    # Require that this call is serviceable by some authenticated context.
    # Since auth is ambient, accept if there exists a coherent active workspace+key OR
    # (for cancellation) allow even if they are suspended/revoked? Real rule only blocks queued->running.
    # We'll authorize if run belongs to an existing workspace and key record; otherwise UNAUTHORIZED.
    if ws is None or key is None:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context found for this run", runId=run.get("id"))

    credential_id = key.get("id")

    # -------- lifecycle transition enforcement with idempotency --------
    current_status = run.get("status")
    terminal_statuses = {"succeeded", "failed", "cancelled", "expired"}
    cancellable_statuses = {"queued", "running"}

    if current_status in terminal_statuses:
        # idempotent: cancelling an already-cancelled run is success (no effect? must still have effect)
        # Since "NO SUCCESS WITHOUT EFFECT", only allow success if we can append a cancellation-request event
        # without changing run status? Real systems accept idempotent cancels as no-op but we must record dynamics.
        if current_status == "cancelled":
            ev = _append_event(events, run.get("id"), "stderr", message=reason or "cancellation requested (idempotent)")
            if isinstance(ev, dict) and ev.get("error"):
                _log_request(credential_id, "error", ev["error"].get("code"))
                return ev
            _save("run_events.json", events)
            key["last_used_at"] = _now_iso()
            key["updated_at"] = _now_iso()
            _save("api_keys.json", api_keys)
            _log_request(credential_id, "ok", None)
            return {
                "run": run,
                "event": ev,
                "idempotent": True,
                "matched_by": match_kind,
            }

        _log_request(credential_id, "error", "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "Cancellation is only allowed when run status is 'queued' or 'running' per lifecycle rules; run is already terminal",
            runId=run.get("id"),
            status=current_status,
            matched_by=match_kind,
        )

    if current_status not in cancellable_statuses:
        _log_request(credential_id, "error", "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "Cancellation is only allowed when run status is 'queued' or 'running' per lifecycle rules",
            runId=run.get("id"),
            status=current_status,
            matched_by=match_kind,
        )

    # perform transition queued/running -> cancelled
    now = _now_iso()
    run["status"] = "cancelled"
    run["error_message"] = (reason.strip() if isinstance(reason, str) and reason.strip() else "cancelled by user")
    run["finished_at"] = now

    started_at = _parse_iso(run.get("started_at")) or _parse_iso(run.get("requested_at"))
    finished_at = _parse_iso(run.get("finished_at"))
    if started_at and finished_at:
        run["runtime_ms"] = _ms_between(started_at, finished_at)
    else:
        # satisfy constraint runtime_ms >= 0
        try:
            run["runtime_ms"] = int(run.get("runtime_ms") or 0)
            if run["runtime_ms"] < 0:
                run["runtime_ms"] = 0
        except Exception:
            run["runtime_ms"] = 0

    # exit_code must be null unless succeeded/failed
    run["exit_code"] = None
    run["updated_at"] = now

    # append event for cancellation request
    ev = _append_event(
        events,
        run.get("id"),
        "run_finished",
        message=run["error_message"],
        data={"final_status": "cancelled", "requested_reason": reason} if reason is not None else {"final_status": "cancelled"},
    )
    if isinstance(ev, dict) and ev.get("error"):
        # don't persist partial state if event append failed
        _log_request(credential_id, "error", ev["error"].get("code"))
        return ev

    # persist
    _save("agent_runs.json", runs)
    _save("run_events.json", events)

    # touch key usage
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    _log_request(credential_id, "ok", None)
    return {
        "run": run,
        "event": ev,
        "matched_by": match_kind,
    }

def claude_code_redact_run_artifact(artifactId, action, redactionNote=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0176000" if __import__("os").path.isdir("./environment_mix/0176000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_event(run_id, event_type, message=None, data=None):
        events = _load("run_events.json")
        max_seq = 0
        for e in events:
            if isinstance(e, dict) and e.get("run_id") == run_id:
                try:
                    s = int(e.get("sequence"))
                    if s > max_seq:
                        max_seq = s
                except Exception:
                    continue
        seq = max_seq + 1
        ev = {
            "id": _gen_id("cce"),
            "run_id": run_id,
            "sequence": seq,
            "event_type": event_type,
            "message": message,
            "data": data,
            "created_at": _now(),
            "updated_at": _now(),
        }
        events.append(ev)
        _save("run_events.json", events)
        return ev

    def _log_request(endpoint, credential_id, status, started_monotonic):
        latency_ms = int(max(0.0, (time.monotonic() - started_monotonic) * 1000.0))
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "created_at": _now(),
            "updated_at": _now(),
        }
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                data = _load(fname)
                if isinstance(data, list):
                    data.append(row)
                    _save(fname, data)
                break

    started = time.monotonic()

    try:
        if not isinstance(artifactId, str) or not artifactId.strip():
            _log_request("claude_code_redact_run_artifact", None, "error", started)
            return _err("VALIDATION_ERROR", "artifactId must be a non-empty string", artifactId=artifactId)
        if not isinstance(action, str) or action not in ("redact", "delete"):
            _log_request("claude_code_redact_run_artifact", None, "error", started)
            return _err("VALIDATION_ERROR", "action must be one of: redact, delete", action=action)
        if redactionNote is not None and not isinstance(redactionNote, str):
            _log_request("claude_code_redact_run_artifact", None, "error", started)
            return _err("VALIDATION_ERROR", "redactionNote must be a string if provided")

        artifacts = _load("run_artifacts.json")
        art_idx = None
        art = None
        for i, a in enumerate(artifacts):
            if isinstance(a, dict) and a.get("id") == artifactId:
                art_idx = i
                art = a
                break

        # Accept and return structured empty response (avoid brittle context mis-resolution).
        if art is None:
            _log_request("claude_code_redact_run_artifact", None, "ok", started)
            return {"artifact": None, "found": False, "changed": False}

        run_id = art.get("run_id")
        runs = _load("agent_runs.json")
        run = None
        for r in runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                run = r
                break

        # If the referenced run is missing, treat as NOT_FOUND (referential integrity broken)
        if run is None:
            _log_request("claude_code_redact_run_artifact", None, "error", started)
            return _err("NOT_FOUND", "Owning run not found for artifact", artifactId=artifactId, runId=run_id)

        # Ambient auth: require an active key in the run's workspace with execute scope (or file scopes).
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        ws = ws_by_id.get(run.get("workspace_id"))

        chosen_key = None
        if ws and ws.get("status") in ("active", "suspended"):
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("workspace_id") != ws.get("id"):
                    continue
                if k.get("status") != "active":
                    continue
                scopes = k.get("scopes") or []
                if not isinstance(scopes, list):
                    continue
                if "execute" in scopes or "file_read" in scopes or "file_write" in scopes:
                    chosen_key = k
                    break

        if chosen_key is None:
            _log_request("claude_code_redact_run_artifact", None, "error", started)
            return _err("UNAUTHORIZED", "Artifact not visible to caller (no suitable active key for workspace)")

        current = art.get("status")
        if current == "deleted":
            _log_request("claude_code_redact_run_artifact", chosen_key.get("id"), "error", started)
            return _err("INVALID_TRANSITION", "Artifact is already deleted", artifactId=artifactId, status=current)

        now = _now()
        changed = False

        if action == "redact":
            if current != "available":
                _log_request("claude_code_redact_run_artifact", chosen_key.get("id"), "error", started)
                return _err(
                    "INVALID_TRANSITION",
                    f"Cannot redact artifact from status '{current}'. Only available->redacted is allowed.",
                    artifactId=artifactId,
                    status=current,
                )
            art["status"] = "redacted"
            # Redaction-safe: remove inline content and storage pointer, keep metadata
            art["inline_text"] = None
            art["storage_url"] = None
            art["updated_at"] = now
            changed = True
            _append_event(
                run_id,
                "error",
                message="Artifact redacted" + (f": {redactionNote}" if redactionNote else ""),
                data={"artifact_id": artifactId, "action": "redact", "note": redactionNote},
            )

        elif action == "delete":
            # available->deleted or redacted->deleted
            if current not in ("available", "redacted"):
                _log_request("claude_code_redact_run_artifact", chosen_key.get("id"), "error", started)
                return _err(
                    "INVALID_TRANSITION",
                    f"Cannot delete artifact from status '{current}'.",
                    artifactId=artifactId,
                    status=current,
                )
            art["status"] = "deleted"
            art["inline_text"] = None
            art["storage_url"] = None
            art["updated_at"] = now
            changed = True
            _append_event(
                run_id,
                "error",
                message="Artifact deleted" + (f": {redactionNote}" if redactionNote else ""),
                data={"artifact_id": artifactId, "action": "delete", "note": redactionNote},
            )

        if not changed:
            _log_request("claude_code_redact_run_artifact", chosen_key.get("id"), "error", started)
            return _err("CONFLICT", "No changes were applied")

        artifacts[art_idx] = art
        _save("run_artifacts.json", artifacts)

        # Update key last_used_at
        key_id = chosen_key.get("id")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _log_request("claude_code_redact_run_artifact", key_id, "ok", started)
        return {"artifact": art, "found": True, "changed": True}
    except Exception as e:
        _log_request("claude_code_redact_run_artifact", None, "error", started)
        return _err("CONFLICT", "Internal error", detail=str(e))
